Parsing a tile map
layers.forEach((l, index) => { 
  const layer = [];
  for (let r = 0; r < rows; r++) { 
  // Loop over rows 
  for (let c = 0; c < columns; c++) { 
    // Loop over columns 
    const gridIndex = (r * columns) + c; 
      // Get index in grid 
