Asynchronous support

Originally, we chose to structure each factory function as shown in the following pseudocode:

function factory(options) {
    // Validate options

    if(!isAsync) {
        return function operator() {
        // ...
        }
    }

    return async function asyncOperator() {
        // ...
    }
}
jsCopy to clipboard

The two inner functions share most of the code, except for one operation; resolving the key. In the async case, the key is an async function that must be called, rather than a string or a buffer. This resulted in code duplication and therefore was not optimal.

We, therefore, used a different approach, as follows:

function factory(options) {
    // Validate options

    return function operator(data, cb) {
        const [callback, promise] = isAsync ? ensurePromiseCallback(cb) : []

        // Perform common operations

        if(!callback) {
            // Perform final operations and return
        }

        getAsyncKey(keyFunction, (err, secret) => {
            if(err) {
                return callback(err)
            }}

            // Perform final operations - Note the code is similar but not the same of the sync case, since there is callback handling
        })



        return promise
    }
}
jsCopy to clipboard

And here’s the definition of  ensurePromiseCallback  and  getAsyncSecret :

function ensurePromiseCallback(callback) {
  if (typeof callback === 'function') {
return [callback]
  }

  let promiseResolve, promiseReject

  const promise = new Promise((resolve, reject) => {
promiseResolve = resolve
promiseReject = reject
  })

  return [
function(err, token) {
      if (err) {
            return promiseReject(err)
      }

      return promiseResolve(token)
},
promise
  ]
}
function getAsyncKey(handler, header, callback) {
  const result = handler(header, callback)

  if (result && typeof result.then === 'function') {
result
      .then(key => {
            // This avoids the callback to be thrown twice if callback throws
            process.nextTick(() => callback(null, key))
      })
      .catch(callback)
  }
}
