Validating our Migration: Hunting for Broken Images

At a cursory glance, it looked like our migration went well. But we know better than to trust gut instinct on a migration of this scale, so we wrote a script to actually check we didn’t break anything.

Since our site is a static site, we were able to do a production build which generated all of our site’s HTML files into a public directory. We then fed each one of those files into a check with broken-link-checker to check for broken images and logged those out to an output file. We actually caught four or five broken images with this script – images that were hard-coded in JavaScript source code files (and not in the markdown files we migrated). This script allowed us to patch and re-test and have confidence in our migration! Here’s the script.

// ./scripts/validate-migration.js
const fs = require("fs/promises");
const path = require("path");
const { HtmlChecker } = require("broken-link-checker");
const glob = require("glob");

const main = async () => {
  // grab our production-built HTML files.
  const htmlFiles = await new Promise((resolve, reject) => {
    glob(
      path.resolve(__dirname, "..", "public/**/*.html"),
      (err, files) => {
        if (err) return reject(err);
        resolve(files);
      }
    );
  });

  // store our results in a broken-images.json file
  const results = await fs
    .readFile(path.resolve(__dirname, "broken-images.json"), "utf-8")
    .then(JSON.parse)
    .catch(() => ({}));

  // for each file, we'll run a broken-site-checker check
  for (const p of htmlFiles) {
    if (results[p] === "all good") continue; // skip already-checked files
    else results[p] = [];

    console.log(`Checking ${p}...`);

    const html = await fs.readFile(p, "utf-8");

    const result = await Promise.race([
      new Promise((resolve, reject) => {
        const checker = new HtmlChecker(
          {},
          {
            complete: () => resolve("done"),
            error: error => reject(error),
            link: result => {
              if (result.broken && result.html.tagName === "img") {
                results[p].push(result.html.attrs.src);
              }
            }
          }
        );

        checker.scan(html, "http://localhost:3001");
      }),
      // Put a max time limit of 30 seconds, just to keep things moving along
      new Promise((_, reject) => setTimeout(reject, 30 * 1000))
    ])
      .then(() => "all good")
      .catch(() => "no bueno"); // capture failures to fully inspect

    if (result === "no bueno") results[p] = "no bueno";
    else if (results[p].length === 0) results[p] = "all good";

    // save our progress along the way.
    await fs.writeFile(
      path.resolve(__dirname, "broken-images.json"),
      JSON.stringify(results, null, 2),
      "utf-8"
    );
  }
};

main().catch(console.error);
