Measuring our Results

To measure our results, we compared the image bandwidth for each of 30 paths from before and after the migration and determined what percent savings we had on each page. We also aggregated the results across all of the 30 pages and computed the percent savings – which is where our 86% savings number came from!

// ./scripts/measure-results.js
const puppeteer = require("puppeteer");
const fs = require("fs/promises");

const main = async () => {
  // pages we wanted to compare
  const pages = ["/", "/about", "/culture", /* ... */];

  // store our results in a results.json file
  const results = await fs
    .readFile("./results.json", "utf-8")
    .then(JSON.parse)
    .catch(() => ({}));

  // Page setup
  const browser = await puppeteer.launch({ headless: false });
  const page = await browser.newPage();
  await page.setViewport({ width: 1080, height: 1024 });
  const devtools = await page.target().createCDPSession();
  await devtools.send("Network.enable");

  // we run one instance/page of puppeteer and need to share some state across event emitters
  // so we store some state here, and pass it along to fns and reset when necessary.
  const state = {
    page,
    responseMap: new Map(),
    total: 0,
    imageCount: 0,
  };

  // Measure image bandwidth can be done by tapping into Network.responseReceived and Network.loadingFinished events
  devtools.on("Network.responseReceived", (evt) => {
    const res = evt.response;
    const headers = res?.headers;

    // only care about image requests
    if (
      headers?.["content-type"]?.includes("image") ||
      headers?.["content-type"]?.includes("binary/octet-stream")
    ) {
      state.responseMap.set(evt.requestId, evt.response);
    }
  });

  devtools.on("Network.loadingFinished", (event) => {
    // check if this event is found in our image response map
    const response = state.responseMap.get(event.requestId);
    if (!response) return;

    // accrue image count/size
    state.imageCount++;
    state.total += Number(event.encodedDataLength);
  });

  // Run the collection for our pages
  results.data = [];
  for (const p of pages) {
    results.data.push(await comparePages(state, p));
  }

  // close up puppeteer
  await browser.close();

  // And then lets aggregate the results and save them.
  const { control, treatment } = results.data.reduce(
    (acc, { control, treatment }) => {
      acc.control += control;
      acc.treatment += treatment;
      return acc;
    },
    { control: 0, treatment: 0 }
  );

  results.total_control = control;
  results.total_treatment = treatment;
  results.total_savings_percent = ((control - treatment) / control) * 100;
  results.pages_crawled = results.data.length;

  await fs.writeFile("./results.json", JSON.stringify(results, null, 2));
};

main().catch(console.error);

// compare control/treatment given a path.
const comparePages = async (state, path) => {
  const a = await getImagePayloadForPage(state, new URL(path, CONTROL_URL).toString());
  const b = await getImagePayloadForPage(state, new URL(path, TREATMENT_URL).toString());

  return {
    path,
    control: a,
    treatment: b,
    percent_savings: ((a - b) / a) * 100,
    image_count: state.imageCount,
  };
};
// our control/treatment URLs, at this point staging has the Cloudinary image URLs
const CONTROL_URL = "https://formidable.com";
const TREATMENT_URL = "https://formidable-3pb2rpm5b-formidable-labs.vercel.app";

// measure the size for a specific url
const getImagePayloadForPage = async (state, url) => {
  state.responseMap.clear();
  state.total = 0;
  state.imageCount = 0;

  await state.page.goto(url);

  // scroll to bottom of page, since many images are lazily loaded in based on visibility
  await state.page.evaluate(() => {
    window.scrollTo({
      left: 0,
      top: window.document.body.scrollHeight,
      behavior: "smooth",
    });
  });

  // wait for network to idle to ensure we captured everything
  await state.page.waitForNetworkIdle();

  return state.total;
};
