import WalletManager from "react-native-wallet-manager";

const blobToDataUrl = async (blob) =>
  new Promise((r) => {
    let a = new FileReader();
    a.onload = r;
    a.readAsDataURL(blob);
  }).then((e) => e.target.result);

export default function App() {
