                <input name="state" {...register("state")} />
                {errors.state && <p>{errors.state.message}</p>}
                <br />

                <label htmlFor="zip">ZIP Code</label>
                <input name="zip" {...register("zip")} />
                {errors.zip && <p>{errors.zip.message}</p>}
                <br />

                <button type="submit">Submit</button>
