This generates something like what’s shown below.

At this point, we’ve primarily just used Victory Native XL’s APIs, but one of the design philosophies of Victory Native XL is to allow the ability to use Skia drawing elements directly so that you can harness the full power of Reanimated and Skia if you so choose.

Let’s add a little bit of over-the-top pizzazz to give a taste of what Reanimated and Skia can do (please don’t actually ship this to users, it’s a bit jarring).

The Area component from victory-native is just a fancy wrapper around Skia <Path /> elements, so we can pass shaders as children to these <Area /> elements to tap into Skia’s shading capabilities. I’ll omit some details, but by using Reanimated SharedValues, shader definitions, and shader “uniforms”, we can create some pretty impressive effects.

import * as React from "react";
import { CartesianChart, Area } from "victory-native";
import { useFont, Skia, Shader, LinearGradient } from "@shopify/react-native-skia";
import { useSharedValue, withTiming, withRepeat } from "react-native-reanimated";
import inter from "assets/inter-medium.ttf"; // <- your font

// ...

export function HelloWorldChart() {
  const font = useFont(inter, 12);

  // 👇 create a "time" variable
  const time = useSharedValue(0);
  // 👇 and loop it
  React.useEffect(() => {
    time.value = withRepeat(
      withTiming(30, { duration: 20 * 1000, easing: Easing.linear}),
      -1,
    );
  }, []);
  const uniforms = useDerivedValue(() => ({
    resW: 500,
    resH: 300,
    time: time.value,
  }));

  return (
    <CartesianChart
      data={DATA}
      xKey="month"
      yKeys={["low", "high"]}
      axisOptions={{ font }}
      domain={{ y: [0] }}
      padding={32}
    >
      {({ points, chartBounds }) => (
        <>
          <Area points={points.high} y0={chartBounds.bottom}>
              {/* 👇 use a shader to color the first Area path */}
              <Shader source={mindbend} uniforms={uniforms} />
          </Area>
          <Area points={points.high} y0={chartBounds.bottom}>
            {/* 👇 and a simple linear gradient for the second */}
            <LinearGradient
              start={{ x: 0, y: chartBounds.bottom }}
              end={{ x: 0, y: chartBounds.top }}
              colors={["#000000", "#00000080"]}
            />
          </Area>
        </>
      )}
    </CartesianChart/>
  );
}

// 👇 Have a shader party, modified from
// https://shaders.skia.org/?id=de2a4d7d893a7251eb33129ddf9d76ea517901cec960db116a1bbd7832757c1f
const mindbend = Skia.RuntimeEffect.Make(`
uniform float time;
uniform float resW;
uniform float resH;

float f(vec3 p) {
  p.z -= time * 10.;
  float a = p.z * .1;
  p.xy *= mat2(cos(a), sin(a), -sin(a), cos(a));
  return .1 - length(cos(p.xy) + sin(p.yz));
}

vec4 main(vec2 FC) { 
  vec3 d = .5 - FC.xy1 / resH;
  vec3 p=vec3(0);
  for (int i = 0; i < 32; i++) {
    p += f(p) * d;
  }
  return ((sin(p) + vec3(2, 5, 12)) / length(p)).xyz1;
}
`)!;
